[{"role": "system", "content": "You turn a plain-English description of a small situation into the represented structure of a governed simulation. Return exactly one JSON object and no prose or markdown. You are describing what exists and what actors may attempt, not what happens: do not describe consequences or rules. Follow the contract exactly; the example shows the format."}, {"role": "user", "content": "{
  "description": "A small airfield office: a brick wall between the office and the hangar, a glass of water on the desk, a helicopter in the hangar, and Sam, a trainee who has never flown.",
  "world_kind": "ongoing",
  "world_kind_rule": "World kind: keeps running. Nothing is ever finally done: work keeps arriving, or people keep living. Represent the state that lets work recur (for example an order's stage that can return to waiting, a plant's thirst counter, a count of waiting items) so the world can keep generating things to do. If it is about people living rather than working, give them needs or resources that change over time (hunger, energy, supplies, growth) as component fields, and several actions to look after them.",
  "world_size_rule": "A whole working system, typically 10 to 30 entities with at most 12 that can act, up to 8 components and 3 to 8 actions. Model it as a chain or web of specialists: several actors, each with their own role who can only do their own step (for a supply chain: raw-material producers, processors, makers of parts, assembly, transport, shops, customers), with intermediate goods passed between them as counted stock (integer quantity fields), so goods flow from one specialist to the next. If the description is about people living rather than producing, model several residents with their own needs and stocks and the resources they depend on, as counted quantities that can be produced, traded or consumed.",
  "contract": {
    "schema_version": "world-substrate-authoring-bundle/v0",
    "world": "{id (lowercase-slug), label, summary (one sentence), location (slug), content_version: 1}",
    "components": "[{name (python identifier), fields: [{name, type, default}]}]",
    "field_types": [
      "boolean",
      "entity_ref",
      "entity_ref_or_null",
      "integer",
      "number",
      "string",
      "string_list"
    ],
    "entities": "[{id (lowercase-slug), label, categories: [nonempty strings], components: {component: {every declared field}}, optional portable: bool, optional owner_ref: 'actor:<id>'|'place:<id>'|'entity:<id>'|'unowned', optional location: <id of the place entity it starts in>}] (owner_ref: use 'actor:<id>' when the owner is a person or business that acts; 'entity:<id>' only for a thing held inside another thing)",
    "actions": "[{kind (lowercase-slug), description, fields: [{name, type in string|integer|number|boolean|entity_ref}]}]",
    "reserved_action_field_names": [
      "actor",
      "kind",
      "base_revision",
      "controller"
    ],
    "presentation": "{assets: {asset_id: {kind: 'emoji', value}}, category_assets: {category: asset_id}, station_roles: {category: one of source|workstation|surface|goal}} (station_roles may be {})",
    "not_modeled": "Top-level list of short plain-English strings naming every part of the description you could NOT represent with this format (for example deadlines, clocks, probabilities, money, distances). Use [] only if everything was represented.",
    "rules": [
      "Every entity component object must list exactly the component's declared fields, with values of the declared type.",
      "entity_ref values must name an entity id that exists in this bundle.",
      "An action that passes something to, or takes something from, another entity (hand over, deliver, carry to, supply, sell to, buy from) must have an entity_ref field naming that other entity (for example 'to', 'source' or 'customer'; field names are Python identifiers, so never 'from'); rules can only change the actor and the entities its fields name.",
      "When goods move between two entities and neither is the actor (a shopkeeper selling the shop's pencils to a customer, a carrier moving stock from the factory to the shop), the action needs an entity_ref field for each of them (for example 'shop' and 'customer', or 'source' and 'to').",
      "Rules change fixed, named quantities and cannot choose which one from a text field, so when different goods move, declare one action per kind of goods (carry-logs, carry-boards), never one carry-goods action with a field naming the goods.",
      "When the description names separate places (rooms, buildings, fields, towns), make each place an entity with category 'place', set every other entity's location to the place it starts in, and give the actors a move action with an entity_ref field 'to' naming the destination place and an entity_ref field 'way' naming what they go through. Represent what lies between two places (a door, a corridor, a wall, a river) as an entity whose component has entity_ref fields naming both places and a boolean saying whether it can be passed (a brick wall: false; an open door: true).",
      "Labels and descriptions are plain English a visitor would use (\"Ava\", \"watering can\"), never internal jargon.",
      "Size: follow world_size_rule.",
      "At least one entity is an actor that can act (give it a component such as worker/person and a clear category).",
      "Every action must be something an actor in this world could plausibly do repeatedly until the situation resolves.",
      "Represent the state the actions change (e.g. stage, count, location) as component fields with typed defaults.",
      "Follow world_kind_rule: a task world must be able to finish (represented state from which 'done' can be read); ongoing and open worlds must have state that keeps changing."
    ]
  },
  "example_bundle": {
    "schema_version": "world-substrate-authoring-bundle/v0",
    "world": {
      "id": "orchard",
      "label": "Orchard",
      "summary": "One worker can eventually pick ripe fruit from a represented tree.",
      "location": "orchard",
      "content_version": 1
    },
    "components": [
      {
        "name": "worker",
        "fields": [
          {
            "name": "stamina",
            "type": "integer",
            "default": 10
          }
        ]
      },
      {
        "name": "fruit",
        "fields": [
          {
            "name": "stage",
            "type": "string",
            "default": "ripe"
          },
          {
            "name": "tree_id",
            "type": "entity_ref",
            "default": "tree-1"
          }
        ]
      }
    ],
    "entities": [
      {
        "id": "ava",
        "label": "Ava",
        "categories": [
          "worker"
        ],
        "components": {
          "worker": {
            "stamina": 10
          }
        }
      },
      {
        "id": "tree-1",
        "label": "Apple tree",
        "categories": [
          "tree"
        ],
        "components": {}
      },
      {
        "id": "apple-1",
        "label": "Apple",
        "categories": [
          "fruit"
        ],
        "portable": true,
        "owner_ref": "place:orchard",
        "components": {
          "fruit": {
            "stage": "ripe",
            "tree_id": "tree-1"
          }
        }
      }
    ],
    "actions": [
      {
        "kind": "pick",
        "description": "Pick one represented fruit.",
        "fields": [
          {
            "name": "fruit",
            "type": "entity_ref"
          }
        ]
      }
    ],
    "presentation": {
      "assets": {
        "worker": {
          "kind": "emoji",
          "value": "\ud83e\uddd1\u200d\ud83c\udf3e"
        },
        "fruit": {
          "kind": "emoji",
          "value": "\ud83c\udf4e"
        }
      },
      "category_assets": {
        "worker": "worker",
        "fruit": "fruit"
      },
      "station_roles": {
        "tree": "source"
      }
    }
  }
}"}]

